      "image": "https://computersweden.se/wp-content/uploads/2026/11/4245011-0-13141600-1793937826-shutterstock_2351071965.jpg?quality=50&#038;strip=all",
      "source": "Computer Sweden",
      "sourceKey": "https://computersweden.se/feed/",
      "timestamp": 1793937600000
